const WINDOW_MS = 6 * 3600 * 1000;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const k of Object.keys(store.seen)) { if (now - store.seen[k].at > 2 * WINDOW_MS) delete store.seen[k]; }
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const wf = (j.workflow && (j.workflow.name || j.workflow.id)) || 'غير معروف';
  const node = (j.execution && j.execution.error && j.execution.error.node && j.execution.error.node.name) || (j.execution && j.execution.lastNodeExecuted) || 'غير محدد';
  const msg = (j.execution && j.execution.error && (j.execution.error.message || j.execution.error.description || j.execution.error.name)) || 'غير محدد';
  const key = [(j.workflow && j.workflow.id) || wf, node, String(msg).slice(0, 120)].join('|');
  const prev = store.seen[key];
  if (prev && now - prev.at < WINDOW_MS) { prev.suppressed = (prev.suppressed || 0) + 1; continue; }
  const suppressed = prev ? (prev.suppressed || 0) : 0;
  store.seen[key] = { at: now, suppressed: 0 };
  out.push({ json: { wf, node, msg: String(msg).slice(0, 600), url: (j.execution && j.execution.url) || '', suppressed } });
}
return out;
